// Generated by tools/generate-tool-types.ts from the server's tool list; regenerate rather than edit.

import type { ToolOutput } from './output.ts';

/** The tools the server offered when this file was generated, one method each. */
export interface MirvaTools {
  /** Leave a comment pinned to a point of a drawing, as the editor's comment tool does; it opens a thread others can reply to. On a canvas the point is in canvas pixels. On a board it is in board space, or in a card's canvas pixels when canvasId names the card. */
  add_comment(args: {
    /** Canvas or board shortId. */
    drawingId: string;
    /** The comment. At most 2500 characters. */
    text: string;
    /** Anchor x. */
    x: number;
    /** Anchor y. */
    y: number;
    /** On a board: shortId of the canvas card the comment pins to. */
    canvasId?: string;
  }): Promise<ToolOutput>;

  /** Pin a sticky note on a board. A note carries its own text, so this is how a board is annotated in place — a direction, a caption, a question against the work it sits beside. It lands exactly where you put it; read list_board_elements first to find clear ground. */
  add_note(args: {
    /** Board to pin the note on. */
    boardId: string;
    /** Note text. Newlines start new lines. At most 100000 characters. */
    text: string;
    /** Board-space left edge. */
    x: number;
    /** Board-space top edge. */
    y: number;
    /** Width in board units. At least 1. Default 500. */
    w?: number;
    /** Height in board units. At least 1. Default 500. */
    h?: number;
    /** Text size in board units. At least 1. Default 40. */
    fontSize?: number;
    /** Note colour as "#rrggbb". */
    color?: number | string;
  }): Promise<ToolOutput>;

  /** Apply one of the editor's layer filters to a canvas paint layer, as its filter panel does: gaussianBlur (radius), motionBlur (distance, angle), hueSaturationLightness (hue, saturation, lightness), brightnessContrast (brightness, contrast) or curves (curvePoints). With a selection active only the selected pixels are filtered. Values outside the editor's range are refused. */
  apply_filter(args: {
    /** Canvas shortId. */
    drawingId: string;
    /** Paint layer to filter. */
    layerId: number;
    /** The filter to run. */
    filter: "gaussianBlur" | "motionBlur" | "hueSaturationLightness" | "brightnessContrast" | "curves";
    /** gaussianBlur: blur radius in pixels. 0 to 100. */
    radius?: number;
    /** motionBlur: blur distance in pixels. 0 to 2000. */
    distance?: number;
    /** motionBlur: direction in degrees. 0 to 360. */
    angle?: number;
    /** hueSaturationLightness: hue shift in degrees. -180 to 180. */
    hue?: number;
    /** hueSaturationLightness: saturation shift. -100 to 100. */
    saturation?: number;
    /** hueSaturationLightness: lightness shift. -100 to 100. */
    lightness?: number;
    /** brightnessContrast: brightness shift. -100 to 100. */
    brightness?: number;
    /** brightnessContrast: contrast shift. -100 to 100. */
    contrast?: number;
    /** curves: one point list per channel, in the order rgb, red, green, blue. At most 4 items. */
    curvePoints?: Array<Array<{
      /** 0 to 1. */
      x: number;
      /** 0 to 1. */
      y: number;
    }>>;
  }): Promise<ToolOutput>;

  /** What differs between a saved version of a board and the board as it is now, object by object: changed since (its content, placement, stacking order or other data), removed since, or added since, each by its object id (uid) and name, and who made its last change since (by: the author, their name, and the agent when an agent made it — "bot" for this bridge, "mirva" for the Mirva agent — and, for a change the Mirva agent made, the chat message whose request it acted on: chat.channelId, chat.messageId). Also whether you may restore from the version, and the key restore_board_version takes to refuse a board that changed after these changes were read. */
  board_version_changes(args: {
    /** Board shortId. */
    boardId: string;
    /** Version id, from list_board_versions. */
    version: string;
  }): Promise<ToolOutput>;

  /** Empty a canvas paint layer of its pixels and keep the layer. Destructive: the pixels cannot be recovered through these tools. */
  clear_layer(args: {
    /** Canvas shortId. */
    drawingId: string;
    /** Paint layer to empty. */
    layerId: number;
  }): Promise<ToolOutput>;

  /** Copy board objects to the clipboard and get back the id to paste them with: canvases, documents, 3D models, videos, notes, board text and sections (a section brings what is inside it). Canvases, documents and media are held at the version they are at now, so a paste recreates that version whatever they become meanwhile. Nothing moves and nothing travels through you — pass the clipboardId to paste_cards, on this board or another. With cut, the objects leave the board once the copy holds them, and the first paste places them as themselves (back on this board, the same cards). With html, the answer also carries the clip as a browser copy writes it (text/html): put on the system clipboard, the person pastes it in a tab of this site, cards and all. Expires a day after the copy. Read list_board_elements for the layer ids. */
  copy_cards(args: {
    /** Board the objects are on. */
    boardId: string;
    /** Layer ids of the board objects to copy; a section brings the objects inside it. */
    layerIds: number[];
    /** Cut instead of copy: the objects leave this board once the copy holds them, and the first paste places them as themselves. */
    cut?: boolean;
    /** Also answer the clip as a browser copy writes it (text/html), for the person to paste in a tab of this site. */
    html?: boolean;
  }): Promise<ToolOutput>;

  /** Put one canvas layer's pixels on the clipboard and get back the id to paste them with, plus the bounds they occupied. The pixels stay here — pass the clipboardId to paste_image, on this canvas or another, and nothing travels through you. Expires ten minutes after the copy. Painted layers only — a layer holding a card or reference has no pixels of its own. To see a layer rather than move it, read it with get_media_pixels. */
  copy_layer(args: {
    /** Canvas shortId. */
    drawingId: string;
    /** Layer to read. */
    layerId: number;
  }): Promise<ToolOutput>;

  /** Start a new Mirva conversation and return its channel. Pass a board shortId to scope the session to that board, so Mirva can see and act on it. */
  create_ai_session(args?: {
    /** Board shortId to scope the session to. Omitted = an unscoped chat. */
    boardId?: string;
  }): Promise<ToolOutput>;

  /** Add a new empty canvas to a board and return its shortId. Omit x/y to have it placed in free space near the middle of the board; give both to pin its top-left corner exactly. */
  create_canvas(args: {
    /** Board shortId to add the canvas to. */
    boardId: string;
    /** Canvas width in pixels. 64 to 8192. Default 1920. */
    width?: number;
    /** Canvas height in pixels. 64 to 8192. Default 1080. */
    height?: number;
    /** Canvas name. Default "New canvas". */
    name?: string;
    /** Fill as "#rrggbb", or a named editor background. */
    background?: string;
    /** Board-space left edge of the card. Requires y; omit both to place in free space. */
    x?: number;
    /** Board-space top edge of the card. Requires x; omit both to place in free space. */
    y?: number;
    /** Board-space point to place the card near when x and y are omitted. */
    anchor?: {
      /** Board-space x. Default 0. */
      x?: number;
      /** Board-space y. Default 0. */
      y?: number;
    };
  }): Promise<ToolOutput>;

  /** Add a new paint layer to a canvas and claim it for this session, returning its layerId. Canvases only — boards hold cards, not paint layers. */
  create_layer(args: {
    /** Canvas shortId. */
    drawingId: string;
    /** Layer name. At most 64 characters. Default "Mirva layer". */
    name?: string;
  }): Promise<ToolOutput>;

  /** Draw a named region on a board. A section is the board's own grouping element — a titled, coloured rectangle that cards sit inside — so a board reads as labelled areas instead of loose cards. It lands exactly where you put it and does not displace what is already there, so size it around the cards it names. */
  create_section(args: {
    /** Board to draw the section on. */
    boardId: string;
    /** Board-space left edge. Default 0. */
    x?: number;
    /** Board-space top edge. Default 0. */
    y?: number;
    /** Width in board units. At least 1. Default 1600. */
    w?: number;
    /** Height in board units. At least 1. Default 1200. */
    h?: number;
    /** Section title, shown on the board. At most 64 characters. */
    name?: string;
    /** Hex tint, e.g. "#C0392B" (default grey). */
    color?: number | string;
  }): Promise<ToolOutput>;

  /** Erase the selected pixels of a canvas paint layer, as the editor's delete does with a selection active. The selection stays for the next edit; undo_edit brings the pixels back. */
  delete_selection(args: {
    /** Canvas shortId. */
    drawingId: string;
    /** Paint layer whose selected pixels are erased. */
    layerId: number;
  }): Promise<ToolOutput>;

  /** Drop the canvas selection so edits reach the whole canvas again. */
  deselect(args: {
    /** Canvas shortId. */
    drawingId: string;
  }): Promise<ToolOutput>;

  /** Draw a rectangle or an ellipse with exact geometry on a canvas paint layer, filled or as an outline of a given stroke width — the editor's shape tools. Where draw_shapes strokes a rect or circle outline with the brush, this draws the shape itself; use it for a solid block, a clean frame, or a shape a fill_area must not leak out of. */
  draw_shape(args: {
    /** Canvas shortId. */
    drawingId: string;
    /** The shape to draw. Default "rect". */
    kind?: "rect" | "ellipse";
    /** Left edge of the shape's box, in canvas pixels. */
    x: number;
    /** Top edge of the shape's box. */
    y: number;
    /** Box width in canvas pixels. */
    w: number;
    /** Box height in canvas pixels. */
    h: number;
    /** Fill the shape rather than stroke its outline. Default true. */
    fill?: boolean;
    /** Outline width in pixels; used when fill is false. 1 to 100. Default 5. */
    strokeWidth?: number;
    /** Hex colour. Default "#E74C3C". */
    color?: string;
    /** Opacity. 0 to 1. Default 1. */
    opacity?: number;
    /** Paint layer to draw on. */
    layerId: number;
  }): Promise<ToolOutput>;

  /** Paint onto a canvas layer you own, in canvas coordinates. "path" strokes an arbitrary point sequence — the primitive a brush produces, and what to reach for when nothing simpler fits; the rest are conveniences over it. Strokes are painted pixels, not vector objects: they cannot be moved or restyled afterwards. Create the layer with create_layer first. */
  draw_shapes(args: {
    /** Canvas shortId. */
    drawingId: string;
    /** Layer to paint on, from create_layer. */
    layerId: number;
    /** Shapes to stroke, in order. */
    shapes: Array<{
      /** path | fill | line | circle | rect | arc */
      kind: string;
      /** For "path": two or more {x, y, pressure?} in stroke order. pressure is 0..1 and tapers the stroke; default 1. */
      points?: Array<{
        x: number;
        y: number;
        /** Stamp strength at this point; lower tapers the stroke. 0 to 1. Default 1. */
        pressure?: number;
      }>;
      x1?: number;
      y1?: number;
      x2?: number;
      y2?: number;
      cx?: number;
      cy?: number;
      r?: number;
      x?: number;
      y?: number;
      w?: number;
      h?: number;
      startAngle?: number;
      endAngle?: number;
    }>;
    /** Hex brush colour. Default "#E74C3C". */
    color?: string;
    /** Brush diameter in pixels. At least 1. Default 8. */
    size?: number;
    /** Edge hardness; lower feathers the stroke. A preset supplies its own. 0 to 1. Default 0.9. */
    hardness?: number;
    /** Stroke opacity. A preset supplies its own. 0 to 1. Default 1. */
    opacity?: number;
    /** Paint per stamp; below 1 the stroke builds up where it overlaps itself. A preset supplies its own. 0 to 1. Default 1. */
    flow?: number;
    /** Stamp distance as a fraction of the size; large values break the stroke into dots. A preset supplies its own. 0.001 to 10. Default 0.2. */
    spacing?: number;
    /** Scale the stamp by each point's pressure (default false). */
    sizePressure?: boolean;
    /** With sizePressure, the smallest stamp as a fraction of the size. A preset supplies its own. 0 to 1. Default 0.2. */
    minSize?: number;
    /** "draw" (default) paints the shapes; "erase" removes paint along them with the same brush settings, colour ignored. */
    mode?: string;
    /** "brush" (default) paints round stamps; "pencil" lays hard square pixels with no pressure sizing; "blend" smudges the paint already on the layer along the strokes instead of adding paint (needs paint under the stroke). */
    tool?: string;
    /** blend only: how far each stamp drags the paint it picked up. A preset supplies its own. 0 to 1. Default 0.4. */
    stretch?: number;
    /** blend only: how much of the brush colour each stamp adds while smudging; 0 is a pure smudge. A preset supplies its own. 0 to 1. Default 0. */
    paint?: number;
    /** A brush preset from list_brush_presets, by name or "set/name" (e.g. "soft charcoal", "general/ink"); its settings are the base, and any setting named here overrides it. Without one the plain round brush paints. */
    preset?: string;
    /** Tip shape id, as list_brush_presets reports under tip; overrides the preset's tip. */
    shape?: string;
    /** The brush panel's advanced settings, laid over the preset's and under the named arguments. A field outside its range is refused rather than clamped. */
    brush?: {
      /** Tip rotation. In degrees. -180 to 180. */
      angle?: number;
      /** Random tip rotation per stamp. In degrees. 0 to 180. */
      angleJitter?: number;
      /** Random dual-tip rotation per stamp. In degrees. 0 to 180. */
      dualAngleJitter?: number;
      /** Tip roundness; below 1 flattens the tip into an ellipse. 0 to 1. */
      roundness?: number;
      /** Random size variation per stamp, as a fraction of the size. 0 to 1. */
      sizeJitter?: number;
      /** With sizeTilt, the smallest stamp as a fraction of the size. 0 to 1. */
      minSizeTilt?: number;
      /** With sizeTilt, the largest stamp as a multiple of the size. 1 to 2. */
      maxSizeTilt?: number;
      /** Scatter across the stroke, as a multiple of the size. 0 to 10. */
      normalSpread?: number;
      /** Scatter along the stroke, as a multiple of the size. 0 to 10. */
      tangentSpread?: number;
      /** Random hue shift per stamp. 0 to 1. */
      hueJitter?: number;
      /** Random saturation shift per stamp. 0 to 1. */
      saturationJitter?: number;
      /** Random brightness shift per stamp. 0 to 1. */
      brightnessJitter?: number;
      /** Random blend toward the background colour per stamp. 0 to 1. */
      foregroundBackgroundJitter?: number;
      /** Dual tip size as a multiple of the brush size. 0.1 to 2. */
      dualSize?: number;
      /** Dual-tip stamp distance as a fraction of its size. 0.001 to 10. */
      dualSpacing?: number;
      /** Dual-tip scatter across the stroke. 0 to 10. */
      dualNormalSpread?: number;
      /** Dual-tip scatter along the stroke. 0 to 10. */
      dualTangentSpread?: number;
      /** How strongly the texture shows. 0 to 1. */
      patternDepth?: number;
      /** Texture scale as a percentage of its own size. 2 to 100. */
      patternScale?: number;
      /** Texture brightness shift. -1 to 1. */
      patternBrightness?: number;
      /** Texture contrast shift. -1 to 1. */
      patternContrast?: number;
      /** Least depth the texture reaches when depth is modulated. 0 to 1. */
      patternMinDepth?: number;
      anglePressure?: boolean;
      angleTilt?: boolean;
      angleToDirection?: boolean;
      angleInitialDirection?: boolean;
      roundnessPressure?: boolean;
      roundnessTilt?: boolean;
      sizeTilt?: boolean;
      flipX?: boolean;
      flipY?: boolean;
      pixelation?: boolean;
      separateSpread?: boolean;
      flowPressure?: boolean;
      flowTilt?: boolean;
      opacityPressure?: boolean;
      opacityTilt?: boolean;
      colorPressure?: boolean;
      colorTilt?: boolean;
      dualSeparateSpread?: boolean;
      dualFlipX?: boolean;
      dualFlipY?: boolean;
      patternInvert?: boolean;
      patternEachStamp?: boolean;
      patternDepthPressure?: boolean;
      patternDepthTilt?: boolean;
      /** A tip id; list_brush_presets names the tips the presets use. */
      dualShape?: string;
      /** A tip id; list_brush_presets names the tips the presets use. */
      patternShape?: string;
      /** How the dual tip combines with the brush tip. */
      dualBlendMode?: "normal" | "multiply" | "color burn" | "linear burn";
      /** How the texture combines with the paint. */
      patternBlendMode?: "multiply" | "color burn" | "color dodge" | "hard mix" | "linear height" | "height" | "overlay";
    };
  }): Promise<ToolOutput>;

  /** Set text with one of the editor's bundled fonts and place it as pixels on a new canvas layer, positioned by its top-left corner. Newlines break lines. Once placed it is paint like any other layer (erase, transform, filter, select on it); the editor's live, editable text layer is not created. Fonts: Inter, Open Sans, Montserrat, Lexend, Lora, Outfit, Roboto Mono, Courier Prime, Caveat, Patrick Hand, Pacifico, Kaushan Script, Bangers, Bungee, Black Ops One, Special Elite, Silkscreen, Galindo, Kavivanar, Rubik Wet Paint, Uncial Antiqua, UnifrakturCook, Klee One, Hachi Maru Pop, Mochiy Pop P One, Noto Sans TC, ZCOOL KuaiLe, Ma Shan Zheng, Zhi Mang Xing, Paperlogy, Cafe24 Syongsyong. */
  draw_text(args: {
    /** Canvas shortId. */
    drawingId: string;
    /** The text; newlines break lines. */
    text: string;
    /** Left edge of the text block in canvas pixels. */
    x: number;
    /** Top edge of the text block in canvas pixels. */
    y: number;
    /** Font size in canvas pixels. 4 to 512. Default 32. */
    size?: number;
    /** Font family name from list_brush_presets' font list. Default "Inter". */
    font?: string;
    /** Text colour as "#rrggbb". Default "#000000". */
    color?: string;
    /** Bold weight. Default false. */
    bold?: boolean;
    /** Italic style. Default false. */
    italic?: boolean;
    /** Horizontal alignment within the block. Default "left". */
    align?: "left" | "center" | "right";
    /** Line height as a multiple of the font size. 0.5 to 4. Default 1.2. */
    lineHeight?: number;
  }): Promise<ToolOutput>;

  /** Copy a canvas layer, pixels and all, as a new layer above it. */
  duplicate_layer(args: {
    /** Canvas shortId. */
    drawingId: string;
    /** Layer to duplicate. */
    layerId: number;
  }): Promise<ToolOutput>;

  /** Rewrite a note's text, by the layer id list_board_elements reports. A board carries questions as well as answers, and a note that can only be pinned leaves the board contradicting the work beside it once the question is settled. The note keeps its position, size, colour and text size; only the words change. */
  edit_note(args: {
    /** Board holding the note. */
    boardId: string;
    /** Layer id from list_board_elements. */
    layerId: number;
    /** Replacement text. Newlines start new lines. At most 100000 characters. */
    text: string;
    /** Text size in board units. Omit to keep the note's own. At least 1. */
    fontSize?: number;
  }): Promise<ToolOutput>;

  /** The paint bucket: flood-fill a canvas paint layer from a point. The region is the connected run of similar colour around the point, within a tolerance; by default it is decided on the layer itself, so an outline drawn with draw_shapes can be filled by clicking inside it. target "all" decides the region against the whole picture and paints it onto the layer; mode "opacity" fills by alpha instead of colour; fillMode "fillRest" paints everything outside the region, "clear" removes the region. */
  fill_area(args: {
    /** Canvas shortId. */
    drawingId: string;
    /** Click position in canvas pixels. */
    x: number;
    /** Click position in canvas pixels. */
    y: number;
    /** Hex fill colour. Default "#E74C3C". */
    color?: string;
    /** Fill opacity. 0 to 1. Default 1. */
    opacity?: number;
    /** How far a pixel may differ from the clicked colour, per channel. 0 to 255. Default 0. */
    tolerance?: number;
    /** Fill only the connected region; false fills every matching pixel. Default true. */
    contiguous?: boolean;
    /** Soften the region's edge. Default false. */
    antiAlias?: boolean;
    /** Which pixels decide the region: the layer, the whole picture, or a neighbouring one. Default "active". */
    target?: "active" | "all" | "above" | "below";
    /** What the fill matches on. Default "color". */
    mode?: "color" | "opacity" | "smart";
    /** Whether to fill the region or the rest, and whether to paint or clear. Default "fill". */
    fillMode?: "fill" | "fillRest" | "clear" | "clearRest";
    /** Paint layer to fill on. */
    layerId: number;
  }): Promise<ToolOutput>;

  /** One drawing or board by shortId: its name, type and timestamps, and for a canvas its stored width and height. */
  get_drawing(args: {
    /** The drawing shortId, as it appears in its URL. */
    shortId: string;
  }): Promise<ToolOutput>;

  /** The most recent messages in a channel, oldest first. Poll after send_message to read a Mirva reply, which is produced asynchronously. An agent reply also reports what it ran (tools), the images it produced (producedImages) and any layers it added to a board (boardEdits) — a generated image is referenced from the tool record, not attached to the message, so the prose alone understates what happened. Fetch a producedImages fileId with read_message_image. */
  get_messages(args: {
    /** Channel to read. */
    channelName: string;
    /** Maximum messages to return. 1 to 100. Default 20. */
    limit?: number;
  }): Promise<ToolOutput>;

  /** Select what is not selected on the canvas and release what is; needs a selection. */
  invert_selection(args: {
    /** Canvas shortId. */
    drawingId: string;
  }): Promise<ToolOutput>;

  /** What sits on a board and where: every card, document, section and label with its bounds, type and the id of whatever it references. Read this before placing anything, so a new element lands in free space rather than on top of existing work. Omit the region to list the whole board — which is what answers "where is X" and "is anything here twice"; a region answers only what is inside it, so a copy of the same card elsewhere goes unreported. */
  list_board_elements(args: {
    /** Board to inspect. */
    boardId: string;
    /** Board-space left edge of the region. Requires y, w and h. */
    x?: number;
    /** Board-space top edge of the region. */
    y?: number;
    /** Region width. At least 1. */
    w?: number;
    /** Region height. At least 1. */
    h?: number;
  }): Promise<ToolOutput>;

  /** The saved versions of a board, newest first: each version's id, label, when it was saved, and whether a person saved it (manual) or it was saved automatically (automatic, among them the ones written before the Mirva agent changed the board, labelled "Before Mirva: …"). */
  list_board_versions(args: {
    /** Board shortId. */
    boardId: string;
  }): Promise<ToolOutput>;

  /** The brush presets draw_shapes accepts as preset: the editor's own brush sets that every account has, each with its set, name, tip shape and whether it carries a texture. Pass tool "eraser", "pencil" or "blend" for the presets those tools accept; the eraser is draw_shapes with mode "erase", the others its tool argument. */
  list_brush_presets(args?: {
    /** Which tool's presets to list. Default "brush". */
    tool?: "brush" | "eraser" | "pencil" | "blend";
  }): Promise<ToolOutput>;

  /** The comment threads on a drawing: where each is anchored (canvas pixels of the canvas named by childId, or board space when there is none), its opening text, author, reply count and state (open or resolved). Read a thread's replies with get_messages on its channelName. */
  list_comments(args: {
    /** Canvas or board shortId. */
    drawingId: string;
  }): Promise<ToolOutput>;

  /** Drawings and boards in the account, newest first. */
  list_drawings(args?: {
    /** Maximum rows to return. 1 to 100. Default 25. */
    limit?: number;
  }): Promise<ToolOutput>;

  /** Merge a canvas paint layer into the layer directly below it, as the layer panel's merge down: the lower layer keeps the combined pixels and the upper layer is removed; the result names the surviving layer. Both must be paint layers, not cards or text. Destructive: the two layers cannot be separated again through these tools. */
  merge_layer_down(args: {
    /** Canvas shortId. */
    drawingId: string;
    /** The upper layer, which merges into the one below it. */
    layerId: number;
  }): Promise<ToolOutput>;

  /** Move or resize any object already on a board, by the layer id list_board_elements reports. A document, section or note takes the width and height given; a canvas, image, video or 3D model card keeps its proportions and is scaled to the width, or to the height when only that is given. Everything but the geometry is preserved: the object keeps its layer id and content, and a canvas card the canvas it shows. */
  move_board_object(args: {
    /** Board holding the object. */
    boardId: string;
    /** Layer id from list_board_elements. */
    layerId: number;
    /** New board-space left edge. Omit to keep. */
    x?: number;
    /** New board-space top edge. Omit to keep. */
    y?: number;
    /** New width. Omit to keep. At least 1. */
    w?: number;
    /** New height. Omit to keep. At least 1. */
    h?: number;
  }): Promise<ToolOutput>;

  /** Join a drawing as a live participant, the way opening it in the editor does, and report its layers with their bounds, plus who is on it. On a board those bounds are where each card sits, so read them before placing something new. Not a prerequisite: every drawing tool attaches the board it names. */
  open_drawing(args: {
    /** The drawing shortId. */
    shortId: string;
  }): Promise<ToolOutput>;

  /** Paste board objects onto a board: those copy_cards put on the clipboard (clipboardId), or those the person copied in a browser tab of this site (clip: the text/html the copy wrote, as the system clipboard holds it). Each canvas, document and media card becomes a new card of this board with the content it had when copied; notes, text and sections are recreated; the first paste of a cut places it as itself. Give x and y for the centre of what lands, or neither for free ground near the board centre. The answer lists anything not recreated, and why. */
  paste_cards(args: {
    /** Board to paste onto. */
    boardId: string;
    /** Handle copy_cards answered with; or give clip. */
    clipboardId?: string;
    /** Board objects the person copied in a browser of this site, as the text/html the copy wrote; instead of clipboardId. At most 16000000 characters. */
    clip?: string;
    /** Board-space x of the pasted objects' centre; with y, or neither. */
    x?: number;
    /** Board-space y of the pasted objects' centre; with x, or neither. */
    y?: number;
  }): Promise<ToolOutput>;

  /** Compose an image into a canvas as a new layer, from image bytes or from a clipboardId copy_layer answered with. Without a rect the image lands at its own size, centred. With one it is cover-cropped to fill that rect — pass exact:true to crop verbatim, or leave it off and a strong aspect mismatch keeps the width and re-centres the height. feather:true fades the edges so a replacement blends into surrounding pixels instead of landing as a hard rectangle. */
  paste_image(args: {
    /** Canvas shortId. */
    drawingId: string;
    /** Base64 image bytes: PNG, JPEG, WebP (lossy or lossless) or GIF, decoding to at most 64 MB. Prefer lossy WebP for photographic content — it carries the largest canvas this app allows in under 20 MB, where the same image as PNG is over 100 MB and is refused. Keep PNG for exact pixels or transparency. Scaling the image to the rect it is going into costs nothing either way, since the paste crops to that rect. */
    image?: string;
    /** Pixels copy_layer put aside, by the clipboardId it answered with, instead of image bytes written out here. The pixels stay on the server, so a copy and a paste move nothing through the caller. Expires ten minutes after the copy. */
    clipboardId?: string;
    /** Canvas-space target for the paste. Omit for the image's own size, centred. */
    rect?: {
      /** Default 0. */
      x?: number;
      /** Default 0. */
      y?: number;
      /** Default 1. */
      w?: number;
      /** Default 1. */
      h?: number;
    };
    /** Crop to the rect verbatim rather than re-centring on aspect mismatch. Default false. */
    exact?: boolean;
    /** Fade the edges so the paste blends. Default false. */
    feather?: boolean;
    /** Turn the source by 90, 180 or 270 degrees before it is measured and cropped. Whole quarter-turns permute pixels rather than resample them, so linework survives the turn unsoftened. Default 0. */
    rotate?: number;
    /** Mirror the source across its vertical axis before pasting. Default false. */
    flip?: boolean;
    /** Layer name. */
    name?: string;
    /** Place the pasted art beneath this existing layer instead of on top. "Beneath" is literal: art under an opaque fill is hidden by it. Compositing a card face wants three layers instead — body, then art above it, then frame details above that. */
    belowLayerId?: number;
  }): Promise<ToolOutput>;

  /** Read a colour off a canvas as the editor's eyedropper does: from the composite the canvas shows, or from one layer's own pixels when layerId is given. radius averages the square around the point (0 reads the single pixel). Reports hex and rgb plus alpha, the coverage of the sampled square; nothing painted there reports picked: false. */
  pick_color(args: {
    /** Canvas shortId. */
    drawingId: string;
    /** Canvas pixel to read, in the canvas's own coordinates. */
    x: number;
    /** Canvas pixel to read, in the canvas's own coordinates. */
    y: number;
    /** Half-width of the sampling square; 0 reads the single pixel, as the eyedropper does. 0 to 8. Default 0. */
    radius?: number;
    /** Read one layer's own pixels instead of the composite the canvas shows. */
    layerId?: number;
  }): Promise<ToolOutput>;

  /** Move a canvas, video or 3D model card already on a board to a new rect, or add one that is not there yet. The card keeps its aspect: width drives the scale and height follows. Use list_board_elements to read what is where first — a rect is taken literally, so overlapping ground is yours to avoid. */
  place_card(args: {
    /** Board holding the card. */
    boardId: string;
    /** Canvas, video or 3D model shortId to place or move. */
    drawingId: string;
    /** Board-space left edge. */
    x: number;
    /** Board-space top edge. */
    y: number;
    /** Width in board units; height follows the card aspect. */
    w: number;
  }): Promise<ToolOutput>;

  /** A rich document's current content as markdown. Read before writing: write_document replaces the whole document, so without this an overwrite cannot see what it is about to destroy, and a caller working from its own copy will silently revert anyone else's edits. */
  read_document(args: {
    /** Document shortId. */
    documentId: string;
  }): Promise<ToolOutput>;

  /** Fetch an image attached to a chat message, by the fileId get_messages reports. This is how a picture the agent produced is actually looked at, and how it is brought back for paste_image. */
  read_message_image(args: {
    /** fileId from a get_messages files entry. */
    fileId: string;
  }): Promise<ToolOutput>;

  /** Redo the last edit this session undid with undo_edit. */
  redo_edit(args: {
    /** Canvas shortId. */
    drawingId: string;
  }): Promise<ToolOutput>;

  /** Delete layers from a drawing. This is destructive and cannot be undone through these tools — the editor's own undo does not reach a change made from outside its history. The result lists what was removed, and any layer it could not act on under skipped — a layer absent from the session reports there rather than as removed. On a board a card layer holds a canvas rather than pixels, and removing it removes that canvas too: to take a card off a board while keeping it, move it away with place_card instead. open_drawing reports each card layer's drawingId, which is what would go with it. */
  remove_layers(args: {
    /** Drawing shortId. */
    drawingId: string;
    /** Layer ids to remove. */
    layerIds: number[];
  }): Promise<ToolOutput>;

  /** A board as it currently renders, as a PNG — its cards laid out in space, including work other participants have in progress. A canvas is a board of one surface and renders the same way; pass layerId there to render one layer instead of the composite. */
  render_board(args: {
    /** The board or canvas to render. */
    shortId: string;
    /** Capture only this layer. Canvases only. */
    layerId?: number;
    /** Region to capture, in the drawing's own coordinates. On a large board capture in parts: the cost follows how many cards the region covers, and a region holding dozens of them can exceed the deadline. On a canvas the region is clipped to the canvas. */
    rect?: {
      /** Left edge. Default 0. */
      x?: number;
      /** Top edge. Default 0. */
      y?: number;
      /** Width; a region with no width captures the whole drawing. Default 0. */
      w?: number;
      /** Height; a region with no height captures the whole drawing. Default 0. */
      h?: number;
    };
    /** Longest edge of the returned image. A canvas renders up to this; a board renders up to the worker's drawing buffer and comes back smaller than asked for when this is larger than that. The result states the size it actually carries. Lower it when the result will be fed back into paste_image, which refuses very large payloads. 1 to 8192. Default 1024. */
    maxDim?: number;
  }): Promise<ToolOutput>;

  /** Restack a canvas's layers, or a board's cards, sections and notes. Order is top-first: the first id ends up above the rest, matching how the layer list reads. Every layer must be listed. */
  reorder_layers(args: {
    /** Canvas shortId. */
    drawingId: string;
    /** Every layer id, topmost first. */
    order: number[];
  }): Promise<ToolOutput>;

  /** Reply in a comment thread of a drawing (a threadId from list_comments or add_comment). */
  reply_comment(args: {
    /** The thread. */
    threadId: string;
    /** The reply. At most 2500 characters. */
    text: string;
  }): Promise<ToolOutput>;

  /** Resize a canvas as the editor's resize dialog does. width and height are the new size in pixels; x and y move the origin in the canvas's own coordinates and default to the current one, so a plain resize keeps the top-left corner and grows or crops at the right and bottom. Layers keep their pixels; what falls outside the new bounds is hidden, not lost. Sizes up to 8192 a side. */
  resize_canvas(args: {
    /** Canvas shortId. */
    drawingId: string;
    /** New width in pixels; the canvas keeps its own when omitted. 1 to 8192. */
    width?: number;
    /** New height in pixels; the canvas keeps its own when omitted. 1 to 8192. */
    height?: number;
    /** New left edge in the canvas's current coordinates; unchanged when omitted. */
    x?: number;
    /** New top edge in the canvas's current coordinates; unchanged when omitted. */
    y?: number;
  }): Promise<ToolOutput>;

  /** Mark a comment thread resolved, or open it again. */
  resolve_comment(args: {
    /** The thread. */
    threadId: string;
    /** true resolves the thread, false reopens it. */
    resolved: boolean;
  }): Promise<ToolOutput>;

  /** Bring a saved version of a board back: the chosen objects, the objects one author changed last since the version (by), or the whole version when neither is given. Choosing an object added since removes it. Restoring by author undoes that author's work and leaves everyone else's; an object someone else changed after it is theirs and stays. The board as it is now is saved as a version first, so the restore can itself be undone. With the key from board_version_changes, a board that changed since is not restored and what differs now is returned instead. */
  restore_board_version(args: {
    /** Board shortId. */
    boardId: string;
    /** Version id, from list_board_versions. */
    version: string;
    /** Object ids (uid) from board_version_changes; omit to restore the whole version. */
    objects?: string[];
    /** An author from board_version_changes (by.author): restore the objects that author changed last. */
    by?: string;
    /** The key board_version_changes returned. */
    key?: string;
  }): Promise<ToolOutput>;

  /** Save the board as it is now as a version, as a person does from the editor's version history: a manual version, kept however many automatic ones follow. Returns its id. */
  save_board_version(args: {
    /** Board shortId. */
    boardId: string;
    /** What the version is, as the history lists it. At most 64 characters. */
    label: string;
  }): Promise<ToolOutput>;

  /** Select the whole canvas. */
  select_all(args: {
    /** Canvas shortId. */
    drawingId: string;
  }): Promise<ToolOutput>;

  /** Select the ellipse inscribed in a rectangle of a canvas, as the editor's ellipse selection does. Strokes, fills, shapes and delete_selection that follow stay inside the selection until it changes or deselect drops it. Coordinates are canvas pixels; each side is at least 2. */
  select_ellipse(args: {
    /** Canvas shortId. */
    drawingId: string;
    /** Left edge of the area. */
    x: number;
    /** Top edge of the area. */
    y: number;
    /** Width of the area, at least 2. */
    w: number;
    /** Height of the area, at least 2. */
    h: number;
    /** How the area combines with the current selection: replace (default), add, subtract or intersect. */
    mode?: string;
  }): Promise<ToolOutput>;

  /** Select a free-form area of a canvas by its outline, as the editor's lasso does: the vertices are joined in order and the outline closes back to the first. Combines with the current selection like select_rect. Coordinates are canvas pixels; three vertices at least. */
  select_lasso(args: {
    /** Canvas shortId. */
    drawingId: string;
    /** Outline vertices in order, three or more; the outline closes by itself. At most 4096 items. */
    points: Array<{
      /** Canvas-space x. */
      x: number;
      /** Canvas-space y. */
      y: number;
    }>;
    /** How the area combines with the current selection. Default "replace". */
    mode?: "replace" | "add" | "subtract" | "intersect";
    /** Soften the outline's edge pixels, as the lasso's anti-alias option does. Default false. */
    antiAlias?: boolean;
  }): Promise<ToolOutput>;

  /** Select the shape of a layer's own pixels, as the editor's "Select layer content" does. This is how an edit is masked to what another layer already covers: a layer's pixels are not a rectangle, an ellipse or an outline the caller could state, so no marquee expresses it. Refused for a card, a text or grid layer, and a layer with no pixels. */
  select_layer_content(args: {
    /** Canvas shortId. */
    drawingId: string;
    /** Layer whose pixels become the selection, from list_layers. */
    layerId: number;
  }): Promise<ToolOutput>;

  /** Select a rectangle of a canvas with the editor's selection tool. Strokes, fills, shapes and delete_selection that follow stay inside the selection until it changes or deselect drops it. Coordinates are canvas pixels; each side is at least 2. */
  select_rect(args: {
    /** Canvas shortId. */
    drawingId: string;
    /** Left edge of the area. */
    x: number;
    /** Top edge of the area. */
    y: number;
    /** Width of the area, at least 2. */
    w: number;
    /** Height of the area, at least 2. */
    h: number;
    /** How the area combines with the current selection: replace (default), add, subtract or intersect. */
    mode?: string;
  }): Promise<ToolOutput>;

  /** Post a message to a chat channel. In a Mirva session this is how you ask Mirva to do something; its reply arrives asynchronously — read it back with get_messages. */
  send_message(args: {
    /** Channel, e.g. "ai-session/<id>" or "drawing/<shortId>". */
    channelName: string;
    /** Message text. A channel other than an AI one takes at most 2500 characters. At most 16000 characters. */
    message: string;
    /** Images to attach, as base64. Mirva sees these, so this is how a reference reaches a generation request rather than only being described. At most 10 items. */
    images?: Array<{
      /** Base64 image bytes, decoding to at most 20 MB. */
      data: string;
      /** File name shown in chat. */
      name?: string;
      /** e.g. "image/png" (default image/png). */
      mimeType?: string;
    }>;
  }): Promise<ToolOutput>;

  /** Change a layer's name, visibility, lock, opacity, opacity lock, blend mode or clipping — the properties the layer panel edits, not its pixels or its position. Naming matters on a board: a card placed by a generation lands as "Placed image" and reads as debris until it is named for what it holds. */
  set_layer(args: {
    /** Canvas or board shortId holding the layer. */
    drawingId: string;
    /** New layer name. */
    name?: string;
    /** Show or hide the layer. */
    visible?: boolean;
    /** A locked layer takes no edits until unlocked. */
    locked?: boolean;
    /** Keep the layer's existing alpha: paint changes colour, never coverage. */
    opacityLocked?: boolean;
    /** Clip the layer to the alpha of the layer below it. */
    clippingGroup?: boolean;
    /** Layer opacity. 0 to 1. */
    opacity?: number;
    /** Blend mode: normal, darken, multiply, color burn, lighten, screen, color dodge, overlay, soft light, hard light, difference, exclusion, hue, saturation, color or luminosity. */
    mode?: string;
    /** Layer id, from list_board_elements. */
    layerId: number;
  }): Promise<ToolOutput>;

  /** Move, rotate, flip or scale a canvas paint layer as the editor's transform and move tools do. Operations apply in the order rotate, flip, scale, translate and are committed to the layer's pixels; with a selection active only the selected pixels move. Reports the layer bounds before and after. A card, a text layer or an empty layer is refused, as is a hidden, locked or fully transparent one. */
  transform_layer(args: {
    /** Canvas shortId. */
    drawingId: string;
    /** Rotation in degrees, clockwise, about the layer centre. -360 to 360. Default 0. */
    rotate?: number;
    /** Mirror the layer about its own centre. */
    flip?: "horizontal" | "vertical";
    /** Uniform scale factor about the layer centre. 0.01 to 100. Default 1. */
    scale?: number;
    /** Horizontal move in canvas pixels. -100000 to 100000. Default 0. */
    dx?: number;
    /** Vertical move in canvas pixels. -100000 to 100000. Default 0. */
    dy?: number;
    /** Paint layer to transform. */
    layerId: number;
  }): Promise<ToolOutput>;

  /** Cut a canvas paint layer back to the canvas bounds, dropping pixels that lie outside it and were never visible. Reports the layer's bounds afterwards. */
  trim_layer(args: {
    /** Canvas shortId. */
    drawingId: string;
    /** Paint layer to trim. */
    layerId: number;
  }): Promise<ToolOutput>;

  /** Remove the board layers an agent turn added, by the messageId of its reply. A generation places its result on the board wherever it chooses, so a run that produced art you are composing yourself leaves a full-size copy behind; this takes it back out. get_messages reports boardEdits on the replies that have any. */
  undo_agent_edits(args: {
    /** messageId of the agent reply, from get_messages. */
    messageId: string;
  }): Promise<ToolOutput>;

  /** Undo this session's last edit on a canvas — a stroke, a fill, a shape, a layer change — the way the editor's undo does. Only what this session drew is undone, never another participant's work; redo_edit brings it back. This is the editor's undo history, unlike undo_agent_edits, which removes the layers an agent's chat reply added. */
  undo_edit(args: {
    /** Canvas shortId. */
    drawingId: string;
  }): Promise<ToolOutput>;

  /** Create a rich document on a board and write its content as markdown. The first "# heading" becomes the document title, so the card on the board is labelled by it. Returns the document id as documentId, which is what to pass back to replace its whole content. */
  write_document(args: {
    /** Board to place the document on. */
    boardId: string;
    /** Markdown. First "# heading" becomes the title. At most 100000 characters. */
    content: string;
    /** Existing document shortId to overwrite. Omit to create one. */
    documentId?: string;
    /** Board-space left edge. Requires y. A document card is 900 wide and A4-proportioned, so leave that much room. */
    x?: number;
    /** Board-space top edge. Requires x. */
    y?: number;
  }): Promise<ToolOutput>;
}

/** The names of those tools. */
export type MirvaToolName = keyof MirvaTools;
